def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_def = 0
    my_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
        if a == 'D':
            my_def += 1
    if opp_def == 0:
        if my_def >= 3:
            return 'D'
        if n < 4:
            return 'C'
        if my_def < 3:
            return 'D'
        return 'C'
    if opp_def >= n * 0.8:
        return 'D'
    if 100 - n <= 5:
        return 'D'
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        else:
            return 'C'
